EXEC(N'UPDATE SCore.EntityQueries SET Statement = N''SELECT 
	[01FDD623-FA79-43E2-AC7B-FA45BEF7FC73].Guid AS ClientAddressId
,	[04DD32E8-AE80-4F81-BD9A-F646441AFBE4].Guid AS ClientContactId
