UPDATE SCore.EntityQueries SET Statement = N'SELECT
		root_hobt.ID,
		root_hobt.RowStatus,
		root_hobt.RowVersion,
		root_hobt.Guid,
		t.Guid AS TransactionID,
		m.Guid AS MilestoneID,
		a.Guid AS ActivityID,
		riba.Guid AS RIBAStageId,
		jps.Guid AS JobPaymentStageId,
		root_hobt.Net,
		root_hobt.Vat,
		root_hobt.Gross,
		root_hobt.VatRate,
		root_hobt.Description,
		root_hobt.LegacyId
		
FROM
		SFin.TransactionDetails root_hobt
JOIN
		SFin.Transactions t ON (t.ID = root_hobt.TransactionID)
JOIN
		SJob.Milestones m ON (m.ID = root_hobt.MilestoneID)
JOIN
		SJob.Activities a ON (a.ID = root_hobt.ActivityID)
JOIN	
		SJob.JobPaymentStages jps ON jps.ID = root_hobt.JobPaymentStageId
JOIN
		SJob.RibaStages riba ON (riba.ID = root_hobt.RIBAStageId)' WHERE ID = 188
