			                                   @ConstructionStageVisitChange =  @ConstructionStageVisitChange,
							  @FeeCapChange = @FeeCapChange,		-- decimal(9, 2)
							  @Guid = @Guid,				-- uniqueidentifier
                                                          @Reason = @Reason' WHERE ID = 193
